{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "@id": "https://kubailabs.com/internal-tools-why-devs-ignore-them/#faq",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Should internal tools use the same auth as public products?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Usually yes, if your public products use an SSO provider that your employees already have accounts with. Reusing the same identity provider means no separate password store, no separate password reset flow, and consistent offboarding when someone leaves. The main exception is tools that need to be reachable from outside the corporate network; those need a separate access model, and that's a security decision, not a UI decision."
      }
    },
    {
      "@type": "Question",
      "name": "How do you get engineers to stop using spreadsheets for internal data?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The spreadsheet wins because it's fast, familiar, and editable. To displace it, the replacement needs to be faster for the specific task and exportable back to a spreadsheet format. A read-only API plus a CSV export endpoint often gets adopted faster than a polished UI, because it slots into the workflow people already have."
      }
    },
    {
      "@type": "Question",
      "name": "What's the minimum viable monitoring for an internal tool?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Access logs with status codes and latency, grouped by endpoint and user, are enough to answer adoption and reliability questions. Add an alert on the 5xx rate for the tool's own API, not on the dependencies it calls — dependency alerts belong to the dependency's owner. If the tool is used during incidents, also alert when it's unreachable, because that's when people will notice."
      }
    },
    {
      "@type": "Question",
      "name": "When should an internal tool be retired?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "When its distinct weekly users drop below the cost of maintaining it, or when the workflow it supports has moved elsewhere. The signal is usually that the only traffic is from a scheduled job that someone forgot to turn off. Check the access logs for the last 90 days; if there's no human traffic and one cron caller, delete the cron job first, then the tool."
      }
    }
  ]
}
